import os

def _env_bool(name, default):
    raw = os.environ.get(name)
    if raw is None:
        return default
    return raw not in {"0", "false", "False"}

def parse_notify_inbox():
    return _env_bool("BRIDGE_NOTIFY_INBOX", True)

