import os

def _default_mcp_dsn():
    dsn = os.environ.get("ARB_MEMORY_MCP_DSN")
    if dsn:
        return dsn
    base = os.environ.get("ARB_MEMORY_DSN", "")
    return base.replace("arb_memory:", "arbmem_mcp:", 1)

